package com.acme.ticketing.sales;

/**
 * Blocks ticket sale when the requested section has no seats remaining.
 */
public class SectionCapacityGuard {

    private final SeatAllocationRepository allocations;

    public SectionCapacityGuard(SeatAllocationRepository allocations) {
        this.allocations = allocations;
    }

    public void assertSeatsAvailable(String eventId, String sectionCode, int requested) {
        int remaining = allocations.remaining(eventId, sectionCode);
        if (remaining < requested) {
            throw new SoldOutSectionException(eventId, sectionCode, remaining, requested);
        }
    }
}

class SoldOutSectionException extends RuntimeException {
    public SoldOutSectionException(String event, String section, int remaining, int requested) {
        super("Only " + remaining + " seats left in " + section + " for " + event + " (requested " + requested + ")");
    }
}

