package com.acme.ticketing.pricing;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Calculates the sale price: face value plus booking fee, tiered by section type.
 */
public class TicketPriceCalculator {

    private final SectionRateTable rates;
    private final BookingFeePolicy fees;

    public TicketPriceCalculator(SectionRateTable rates, BookingFeePolicy fees) {
        this.rates = rates;
        this.fees = fees;
    }

    public SalePrice price(String eventId, String sectionCode, int quantity) {
        BigDecimal face = rates.faceValue(eventId, sectionCode);
        BigDecimal faceTotal = face.multiply(BigDecimal.valueOf(quantity));
        BigDecimal fee = fees.feeFor(sectionCode, faceTotal);
        BigDecimal total = faceTotal.add(fee);
        return new SalePrice(faceTotal, fee, total.setScale(2, RoundingMode.HALF_UP));
    }
}

