package com.acme.ticketing.web;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Seat purchase endpoint: reserve, charge, issue tickets.
 */
@RestController
public class SeatPurchaseController {

    private final SectionCapacityGuard capacity;
    private final SeatReservationService reservations;
    private final PaymentProcessor payments;
    private final TicketIssuer ticketIssuer;

    public SeatPurchaseController(SectionCapacityGuard capacity,
                                  SeatReservationService reservations,
                                  PaymentProcessor payments,
                                  TicketIssuer ticketIssuer) {
        this.capacity = capacity;
        this.reservations = reservations;
        this.payments = payments;
        this.ticketIssuer = ticketIssuer;
    }

    @PostMapping("/sales")
    public SaleReceipt purchase(@RequestBody SeatPurchaseRequest req) {
        capacity.assertSeatsAvailable(req.getEventId(), req.getSectionCode(), req.getSeatIds().size());
        reservations.reserve(req.getEventId(), req.getSeatIds(), req.getCustomerId());
        payments.charge(req.getCustomerId(), req.getTotal());
        TicketBatch tickets = ticketIssuer.issue(req.getEventId(), req.getSeatIds(), req.getCustomerId());
        return new SaleReceipt(tickets.getSaleId(), tickets.getTicketCodes());
    }
}

