package com.acme.ticketing.organiser;

import java.time.Instant;

/**
 * Opens ticket sales for an event and notifies waitlisted customers.
 */
public class OpenSalesService {

    private final EventRepository events;
    private final WaitlistRepository waitlist;
    private final NotificationGateway notifier;

    public OpenSalesService(EventRepository events, WaitlistRepository waitlist, NotificationGateway notifier) {
        this.events = events;
        this.waitlist = waitlist;
        this.notifier = notifier;
    }

    public void open(String eventId, Instant opensAt) {
        Event e = events.require(eventId);
        if (e.getStatus() != EventStatus.SCHEDULED) {
            throw new IllegalStateException("Event is not in SCHEDULED state");
        }
        e.setStatus(EventStatus.ON_SALE);
        e.setSalesOpenAt(opensAt);
        events.save(e);
        for (String customerId : waitlist.membersOf(eventId)) {
            notifier.send(customerId, "Tickets for " + e.getTitle() + " are now on sale");
        }
    }
}

