package com.acme.ticketing.resale;

/**
 * Enforces resale eligibility: resale must be enabled and channel must be official.
 */
public class ResaleEligibilityPolicy {

    private final EventRepository events;

    public ResaleEligibilityPolicy(EventRepository events) {
        this.events = events;
    }

    public boolean isEligible(Ticket ticket, String channel) {
        Event e = events.require(ticket.getEventId());
        if (!e.isResaleEnabled()) {
            return false;
        }
        return "OFFICIAL".equalsIgnoreCase(channel);
    }

    public void assertEligible(Ticket ticket, String channel) {
        if (!isEligible(ticket, channel)) {
            throw new ResaleNotPermittedException(ticket.getId());
        }
    }
}

class ResaleNotPermittedException extends RuntimeException {
    public ResaleNotPermittedException(String ticketId) {
        super("Ticket " + ticketId + " is not eligible for resale through this channel");
    }
}

