package com.acme.ticketing.audit;

import java.math.BigDecimal;
import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an immutable record of each ticket sale.
 */
public class TicketSaleRecorder {

    private final EntityManager em;

    public TicketSaleRecorder(EntityManager em) {
        this.em = em;
    }

    public void record(String eventId, String seatId, String customerId, BigDecimal pricePaid, String channel) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            TicketSaleEntry e = new TicketSaleEntry();
            e.setEventId(eventId);
            e.setSeatId(seatId);
            e.setCustomerId(customerId);
            e.setPricePaid(pricePaid);
            e.setChannel(channel);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

