/* daily_settlement.c - write daily ticket settlement report per event */
#include <stdio.h>
#include "ticketing_db.h"

int write_daily_settlement(const char *business_date, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "event_id,gross_sales,refunds,net_revenue\n");

    db_cursor_t *cur = NULL;
    if (db_open_daily_settlement_cursor(&cur, business_date) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    settlement_row_t row;
    while (db_settlement_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%.2f,%.2f,%.2f\n",
                row.event_id, row.gross_sales, row.refunds, row.net_revenue);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

